#!/usr/bin/env bash
# Launcher of the small-reservoir tier (spec docs/plans/2026-10-28-small-tier-spec.md): 10 processes over the list (all
# grids are small), a single-process pass for memory retries, the 45 km edge pass, the lock, then the widening in 10
# processes and its lock. One BLAS / OpenMP thread per process (as gdw_ext_batch.sh). Logs in the run folder.
# DO NOT EDIT THIS FILE WHILE IT IS RUNNING: bash reads a script while executing it.
# Usage: bash 04_Code/scripts/small_tier_batch.sh
cd "$(dirname "$0")/../.." || exit 1
LOG=05_Results/by_date/2026-10-28/small_tier_v1/logs; mkdir -p "$LOG"
export PYTHONIOENCODING=utf-8 OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
run() { .venv/Scripts/python.exe -I 04_Code/scripts/small_tier_v1.py "$@" 2>&1 | grep --line-buffered -v "^r2 {"; }
N=10
for i in $(seq 1 $N); do run run --part "$i/$N" >> "$LOG/run_${i}of${N}.log" & done; wait
run run >> "$LOG/retry.log"
run retry-edge >> "$LOG/edge.log"
run lock >> "$LOG/lock.log"
for i in $(seq 1 $N); do run widen --part "$i/$N" >> "$LOG/widen_${i}of${N}.log" & done; wait
run widen >> "$LOG/widen_retry.log"
run widen-lock >> "$LOG/widen_lock.log"
echo "batch finished $(date -Iseconds)" >> "$LOG/batch.log"
